使用示例： //TCP客户端示例
tcp_socketclient;
client.open(AF_INET);

autoserver=ip_address::parse("192.168.1.100",ports(8080));
if(client.connect(*server,milliseconds(3000))){
stringrequest="GET/HTTP/1.1\r\nHost:example.com\r\n\r\n";
client.send_all(request.view());

charbuffer[4096];
ssize_treceived=client.receive({buffer,sizeof(buffer)});
if(received>0){
println(string_view(buffer,received));
}
}

//TCP服务器示例
tcp_socketserver;
server.open(AF_INET);
autolocal=ip_address::any(ports(8080));
server.bind(local);
server.listen(128);

autoclient_sock=server.accept();//接受连接
//与客户端通信...
